  1	using System.IO;
  2	
  3	namespace DevX.Cli;
  4	
  5	public sealed class SandboxManager : IDisposable
  6	{
  7	    private readonly string _sandboxRoot;
  8	    private readonly string _originalRoot;
  9	    private bool _disposed;
 10	
 11	    public string SandboxRoot => _sandboxRoot;
 12	    public string OriginalRoot => _originalRoot;
 13	
 14	    public SandboxManager(string originalRoot)
 15	    {
 16	        _originalRoot = Path.GetFullPath(originalRoot);
 17	        _sandboxRoot = Path.Combine(Path.GetTempPath(), $"devx-sandbox-{Guid.NewGuid():N}");
 18	        Directory.CreateDirectory(_sandboxRoot);
 19	    }
 20	
 21	    /// <summary>
 22	    /// Copies the source tree into the sandbox, excluding ignored directories.
 23	    /// </summary>
 24	    public void CopySourceTree()
 25	    {
 26	        CopyDirectory(_originalRoot, _sandboxRoot);
 27	    }
 28	
 29	    /// <summary>
 30	    /// Copies changed files from sandbox back to the original repository.
 31	    /// </summary>
 32	    public void ApplyChanges()
 33	    {
 34	        foreach (var sandboxFile in EnumerateFiles(_sandboxRoot))
 35	        {
 36	            var relativePath = Path.GetRelativePath(_sandboxRoot, sandboxFile);
 37	            var originalFile = Path.Combine(_originalRoot, relativePath);
 38	            var originalDir = Path.GetDirectoryName(originalFile)!;
 39	            Directory.CreateDirectory(originalDir);
 40	            File.Copy(sandboxFile, originalFile, overwrite: true);
 41	        }
 42	    }
 43	
 44	    /// <summary>
 45	    /// Returns a list of files that differ between sandbox and original.
 46	    /// </summary>
 47	    public IReadOnlyList<string> GetChangedFiles()
 48	    {
 49	        var changed = new List<string>();
 50	        foreach (var sandboxFile in EnumerateFiles(_sandboxRoot))
 51	        {
 52	            var relativePath = Path.GetRelativePath(_sandboxRoot, sandboxFile);
 53	            var originalFile = Path.Combine(_originalRoot, relativePath);
 54	            if (!File.Exists(originalFile))
 55	            {
 56	                changed.Add(relativePath + " (new)");
 57	                continue;
 58	            }
 59	            var sandboxContent = File.ReadAllText(sandboxFile);
 60	            var originalContent = File.ReadAllText(originalFile);
 61	            if (sandboxContent != originalContent)
 62	            {
 63	                changed.Add(relativePath);
 64	            }
 65	        }
 66	        return changed;
 67	    }
 68	
 69	    /// <summary>
 70	    /// Returns a unified diff of all changed files.
 71	    /// </summary>
 72	    public string GetUnifiedDiff(int contextLines = 3)
 73	    {
 74	        var sb = new System.Text.StringBuilder();
 75	        foreach (var sandboxFile in EnumerateFiles(_sandboxRoot))
 76	        {
 77	            var relativePath = Path.GetRelativePath(_sandboxRoot, sandboxFile);
 78	            var originalFile = Path.Combine(_originalRoot, relativePath);
 79	            if (!File.Exists(originalFile))
 80	            {
 81	                sb.AppendLine($"--- /dev/null");
 82	                sb.AppendLine($"+++ {relativePath}");
 83	                var lines = File.ReadAllLines(sandboxFile);
 84	                sb.AppendLine($"@@ -0,0 +1,{lines.Length} @@");
 85	                foreach (var line in lines)
 86	                {
 87	                    sb.AppendLine($"+{line}");
 88	                }
 89	                sb.AppendLine();
 90	                continue;
 91	            }
 92	            var originalLines = File.ReadAllLines(originalFile);
 93	            var sandboxLines = File.ReadAllLines(sandboxFile);
 94	            if (originalLines.SequenceEqual(sandboxLines))
 95	            {
 96	                continue;
 97	            }
 98	            sb.AppendLine($"--- {relativePath}");
 99	            sb.AppendLine($"+++ {relativePath}");
100	            // Simple line-by-line diff
101	            var maxLen = Math.Max(originalLines.Length, sandboxLines.Length);
102	            for (var i = 0; i < maxLen; i++)
103	            {
104	                var orig = i < originalLines.Length ? originalLines[i] : null;
105	                var sand = i < sandboxLines.Length ? sandboxLines[i] : null;
106	                if (orig != sand)
107	                {
108	                    if (orig != null) sb.AppendLine($"-{orig}");
109	                    if (sand != null) sb.AppendLine($"+{sand}");
110	                }
111	            }
112	            sb.AppendLine();
113	        }
114	        return sb.ToString();
115	    }
