117	    public void Dispose()
118	    {
119	        if (_disposed) return;
120	        _disposed = true;
121	        try
122	        {
123	            if (Directory.Exists(_sandboxRoot))
124	            {
125	                Directory.Delete(_sandboxRoot, recursive: true);
126	            }
127	        }
128	        catch
129	        {
130	            // Best effort cleanup
131	        }
132	    }
