134	    private static void CopyDirectory(string source, string dest)
135	    {
136	        var ignored = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
137	        {
138	            ".git", ".devx", "bin", "obj", ".vs", ".idea", "node_modules", "dist", "out", "coverage"
139	        };
140	
141	        foreach (var dir in Directory.EnumerateDirectories(source))
142	        {
143	            var name = Path.GetFileName(dir);
144	            if (ignored.Contains(name)) continue;
145	            var destDir = Path.Combine(dest, name);
146	            Directory.CreateDirectory(destDir);
147	            CopyDirectory(dir, destDir);
148	        }
149	
150	        foreach (var file in Directory.EnumerateFiles(source))
151	        {
152	            var name = Path.GetFileName(file);
153	            if (ignored.Contains(name)) continue;
154	            var destFile = Path.Combine(dest, name);
155	            File.Copy(file, destFile, overwrite: true);
156	        }
157	    }
158	
159	    private static IEnumerable<string> EnumerateFiles(string root)
160	    {
161	        var ignored = new HashSet<string>(StringComparer.OrdinalIgnoreCase)
162	        {
163	            ".git", ".devx", "bin", "obj", ".vs", ".idea", "node_modules", "dist", "out", "coverage"
164	        };
165	
166	        foreach (var file in Directory.EnumerateFiles(root, "*", SearchOption.AllDirectories))
167	        {
168	            var parts = file.Split(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
169	            if (parts.Any(p => ignored.Contains(p))) continue;
170	            yield return file;
171	        }
172	    }
173	}
